create or replace function app.convert_portal_inquiry_to_investor(p_inquiry_id uuid,p_investor_id uuid) returns public.portal_inquiries language plpgsql security definer set search_path='' as $$declare v_actor uuid:=auth.uid();v_row public.portal_inquiries%rowtype;v_investor public.investors%rowtype;v_account public.user_accounts%rowtype;begin if v_actor is null or not app.has_permission('inquiries.convert') then raise exception 'Missing permission: inquiries.convert' using errcode='42501';end if;if not app.has_permission('investors.create') then raise exception 'Missing permission: investors.create' using errcode='42501';end if;select * into v_row from public.portal_inquiries where id=p_inquiry_id for update;if not found then raise exception 'Inquiry not found.' using errcode='P0002';end if;if v_row.status not in('new','in_progress') or v_row.converted_investor_id is not null then raise exception 'Inquiry is not eligible for conversion.' using errcode='23514';end if;select * into v_investor from public.investors where id=p_investor_id for share;if not found then raise exception 'Investor not found.' using errcode='P0002';end if;if v_investor.status in('rejected','inactive') then raise exception 'Investor status is not eligible for inquiry conversion.' using errcode='23514';end if;select * into v_account from public.user_accounts where id=p_investor_id for share;if not found or v_account.account_type<>'investor' or v_account.status<>'active' then raise exception 'Investor account must be active.' using errcode='23514';end if;if v_account.email is null or lower(btrim(v_account.email))<>lower(btrim(v_row.email)) then raise exception 'Investor email must match inquiry email.' using errcode='23514';end if;update public.portal_inquiries set converted_investor_id=p_investor_id,status='converted' where id=p_inquiry_id returning * into v_row;insert into public.audit_logs(actor_id,actor_type,action,entity_type,entity_id,summary,changes) values(v_actor,app.current_actor_type(),'inquiry.converted','portal_inquiry',p_inquiry_id,'Portal inquiry converted to investor',jsonb_build_object('investor_id',p_investor_id));return v_row;end$$;
create or replace function app.set_portal_inquiry_status(p_inquiry_id uuid,p_status public.inquiry_status) returns public.portal_inquiries language plpgsql security definer set search_path='' as $$declare v_actor uuid:=auth.uid();v_old public.portal_inquiries%rowtype;v_new public.portal_inquiries%rowtype;begin if v_actor is null or not app.has_permission('inquiries.handle') then raise exception 'Permission denied.' using errcode='42501';end if;if p_status='converted' then raise exception 'Converted status can only be set by convert_portal_inquiry_to_investor.' using errcode='42501';end if;select * into v_old from public.portal_inquiries where id=p_inquiry_id for update;if not found then raise exception 'Inquiry not found.' using errcode='P0002';end if;if v_old.status='converted' or v_old.converted_investor_id is not null then raise exception 'Converted inquiry status is immutable.' using errcode='23514';end if;update public.portal_inquiries set status=p_status where id=p_inquiry_id returning * into v_new;insert into public.audit_logs(actor_id,actor_type,action,entity_type,entity_id,summary,changes) values(v_actor,app.current_actor_type(),'inquiry.status_changed','portal_inquiry',p_inquiry_id,'Inquiry status updated',jsonb_build_object('from',v_old.status,'to',v_new.status));return v_new;end$$;